public Resultado<ClienteDto> Obter(string clienteId)
{
    var cliente = _clientes.FirstOrDefault(c => c.Id == clienteId);   // linha 1

    if (cliente.Nome == null)                                          // linha 2
        return Resultado<ClienteDto>.Falha("Cliente não encontrado");

    return Resultado<ClienteDto>.Ok(MapearParaDto(cliente));
}

public Resultado<DocumentoDto> ObterProcuracao(List<Documento> documentos)
{
    Documento procuracao = null;
    foreach (var d in documentos)
    {
        if (d.Tipo == "Procuração") { procuracao = d; break; }
    }

    if (procuracao == null)
        return Resultado<DocumentoDto>.Falha("Cliente sem procuração");

    return Resultado<DocumentoDto>.Ok(MapearParaDto(procuracao));
}

